// Telling a GENERATED composition root from a hand-owned one.
//
// Both toolchains write the marker as a BANNER — the first line of the file they
// generate, and the first thing on it:
//
//   // BEDROCK_SERVE_MARKER — the composition root at the git root.
//   // GENERATED by `sprig build --rune` — the single-origin composition root …   (1.x)
//
// `writeRuneServe` refuses to clobber a serve.ts without one and `sprig clean`
// only removes one with it, so a hand-written root is never overwritten nor
// deleted — whichever CLI ran.
//
// The test used to be `src.includes(MARKER)`: the marker ANYWHERE in the file.
// That made any MENTION of the name count as the marker — including a file whose
// whole point was explaining that it has none. infra's hand-owned root opened
// with "It carries no BEDROCK_SERVE_MARKER, and that is the point: the toolchain
// refuses to overwrite a serve.ts without the marker, so this file survives
// `sprig build`", and that sentence is what got it overwritten on the next build:
// its `InfraFrontend()` ui slot replaced by a plain `Frontend()`, the publication
// of the keystone project id dropped — and with no project id the auth unit took
// its hermetic branch and accepted a token-less login (coms 20260921T181052Z-w5-55966,
// REQ-010). So the marker counts only as the banner it is written as, and prose
// about it is inert.
//
// Lives in its own module so it is testable without running the CLI.
import { BEDROCK_SERVE_MARKER } from "@techgoose-labs/bedrock/artifact";

/** The banner the 1.x CLI wrote. A serve.ts carrying it is by definition
 *  generated — refusing to regenerate it stranded every 1.x app at "already
 *  exists and was NOT generated" on its first 2.x build, one step into the
 *  migration. So it counts as generated too, for regeneration and for clean. */
export const LEGACY_SERVE_MARKER = "GENERATED by `sprig build --rune`";

/** The file's banner — the text of a leading `//` comment on line one — or null
 *  when line one is not a comment at all. Tolerates a BOM and CRLF, because a
 *  generated file that made a round trip through another tool is still generated. */
function banner(src: string): string | null {
  const first = src.replace(/^﻿/, "").split(/\r?\n/, 1)[0];
  const open = /^\s*\/\/\s*/.exec(first);
  return open ? first.slice(open[0].length) : null;
}

/** Was this serve.ts written by a toolchain — 2.x or 1.x? True only for the
 *  generated BANNER, never for prose naming a marker. */
export function isGeneratedServe(src: string): boolean {
  const b = banner(src);
  return b !== null &&
    (b.startsWith(BEDROCK_SERVE_MARKER) || b.startsWith(LEGACY_SERVE_MARKER));
}

/** Was this serve.ts written by the 1.x CLI? The build says so out loud when it
 *  regenerates one, so a migrating app knows what just changed under it. */
export function isLegacyServe(src: string): boolean {
  return banner(src)?.startsWith(LEGACY_SERVE_MARKER) ?? false;
}
